```javascript
// e2e/ui-smoke-test.spec.mjs - line 17 test
test("Admin UI login with openidm-admin succeeds", async ({ page }) => {
    await page.goto(`${BASE_URL}/admin/`);
    await page.waitForSelector("#login", { timeout: 30000 });

    await page.fill("#login", ADMIN_USER);
    await page.fill("#password", ADMIN_PASS);

    // Use a more targeted selector and wait for navigation/response after click
    await Promise.all([
        page.waitForNavigation({ waitUntil: "networkidle", timeout: 30000 }).catch(() => {}),
        page.click("input[type=submit], button[type=submit], #loginButton, .btn-primary"),
    ]);

    // Give the SPA time to transition
    await page.waitForFunction(() => {
        return document.querySelector("#content") !== null
            || document.querySelector(".navbar") !== null
            || document.querySelector("#wrapper") !== null;
    }, { timeout: 30000 });

    const loginField = await page.$("#login");
    const isLoginVisible = loginField ? await loginField.isVisible() : false;
    expect(isLoginVisible).toBe(false);
});
```

